B.apj=new A.lJ("\ud83c\udfe0","Apartamento peque\xf1o","2 habitaciones, barrio tranquilo. Ideal para empezar.",5e4,400,8e4)
B.apl=new A.lJ("\ud83c\udfe1","Casa familiar","3 hab. + jard\xedn. Perfecta para cuando tengas familia.",12e4,850,2e5)
